const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const escapeHTML = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const channels = [
  {name:'Microphone',device:'Shure SM7B · Scarlett 2i2',icon:'♩',color:'#b7a0f8',db:-3,level:78,effects:3,pan:0,mute:false,solo:false},
  {name:'Desktop audio',device:'System audio · WASAPI',icon:'▣',color:'#91bcd7',db:-8,level:62,effects:0,pan:0,mute:false,solo:false},
  {name:'Music',device:'Spotify · Application',icon:'♫',color:'#a2c9ad',db:-14,level:48,effects:1,pan:0,mute:false,solo:false},
  {name:'Soundboard',device:'PirateWave · Internal',icon:'▦',color:'#dfb392',db:-6,level:0,effects:0,pan:0,mute:false,solo:false}
];
let activeView = 'mixer', toastTimer, dialogCallback, sceneName = 'Streaming setup', monitoring = true;
const descriptions = {
  mixer:['The mixing desk.','Every source. Every destination. All in your control.','Mixer','＋ Add channel'],
  effects:['Shape your sound.','A little polish. A new character. Make every signal yours.','Effects rack','＋ Add effect'],
  soundboard:['Right on cue.','Your favorite sounds, one shortcut away.','Soundboard','＋ Add sound'],
  routing:['Connect the dots.','Turn individual sources into a signal flow that makes sense.','Routing','＋ Add node']
};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function showView(view){activeView=view;$$('.view').forEach(el=>el.classList.toggle('active',el.id===view));$$('[data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===view);el.setAttribute('aria-current',el.dataset.view===view?'page':'false');});const d=descriptions[view];$('#page-title').textContent=d[0];$('#page-description').textContent=d[1];$('#breadcrumb').textContent=d[2];$('#main-action').textContent=d[3];if(view==='routing')requestAnimationFrame(drawWires);}
$$('[data-view]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.view)));
$('#open-routing').onclick=()=>showView('routing');$('#open-soundboard').onclick=()=>showView('soundboard');
function renderChannels(){
  $('#channels').style.gridTemplateColumns=channels.length>4?'repeat(auto-fit,minmax(130px,1fr))':'';
  $('#channels').innerHTML=channels.map((c,i)=>`<article class="channel ${c.mute?'muted':''} ${c.solo?'soloed':''}" style="--channel-color:${c.color}" data-channel="${i}"><div class="channel-head"><div class="channel-top"><span class="source-icon">${c.icon}</span><button class="more" aria-label="Edit ${escapeHTML(c.name)}" data-edit="${i}">···</button></div><h3>${escapeHTML(c.name)}</h3><select aria-label="${escapeHTML(c.name)} input device" data-device="${i}"><option>${escapeHTML(c.device)}</option><option>System default</option><option>Scarlett 2i2 · Input 1</option><option>PirateWave Virtual Audio</option></select></div><div class="channel-body"><div class="pan-label"><span>L</span><b id="pan-value-${i}">${c.pan===0?'C':Math.abs(c.pan)+(c.pan<0?' L':' R')}</b><span>R</span></div><input class="pan-range" type="range" min="-100" max="100" value="${c.pan}" data-pan="${i}" aria-label="${escapeHTML(c.name)} pan"><div class="fader-area"><div class="meter-scale"><span>+6</span><span>0</span><span>−6</span><span>−12</span><span>−24</span><span>−∞</span></div><input class="fader" type="range" min="-60" max="6" value="${c.db}" step="1" data-fader="${i}" aria-label="${escapeHTML(c.name)} gain"><div class="stereo-meter" aria-label="Simulated signal level"><i style="--level:${c.level}%"></i><i style="--level:${Math.max(0,c.level-7)}%"></i></div></div><div class="db-value" id="db-${i}">${c.db===-60?'−∞':c.db.toFixed(1)}<span>dB</span></div></div><div class="channel-controls"><button class="square-button mute" data-mute="${i}" aria-pressed="${c.mute}" aria-label="Mute ${escapeHTML(c.name)}">M</button><button class="square-button" data-solo="${i}" aria-pressed="${c.solo}" aria-label="Solo ${escapeHTML(c.name)}">S</button></div><div class="channel-route"><span class="route-dot"></span>Monitor <span>+</span> Stream mix</div><button class="effect-link" data-effects="${i}"><span>◈</span><span>${c.effects?c.effects+' effects active':'Add effects'}</span><span>↗</span></button></article>`).join('');
  $$('[data-fader]').forEach(input=>input.oninput=()=>{const i=+input.dataset.fader;channels[i].db=+input.value;$(`#db-${i}`).innerHTML=`${+input.value===-60?'−∞':(+input.value).toFixed(1)}<span>dB</span>`;$$('.stereo-meter i',input.parentElement).forEach((m,j)=>m.style.height=Math.max(0,channels[i].level+(+input.value+3)-j*7)+'%');});
  $$('[data-pan]').forEach(input=>input.oninput=()=>{channels[+input.dataset.pan].pan=+input.value;$(`#pan-value-${input.dataset.pan}`).textContent=+input.value===0?'C':Math.abs(+input.value)+(+input.value<0?' L':' R');});
  $$('[data-mute]').forEach(b=>b.onclick=()=>{channels[+b.dataset.mute].mute=!channels[+b.dataset.mute].mute;renderChannels();});
  $$('[data-solo]').forEach(b=>b.onclick=()=>{channels[+b.dataset.solo].solo=!channels[+b.dataset.solo].solo;renderChannels();});
  $$('[data-device]').forEach(s=>s.onchange=()=>{channels[+s.dataset.device].device=s.value;toast('Input device updated in preview');});
  $$('[data-effects]').forEach(b=>b.onclick=()=>{const name=channels[+b.dataset.effects].name;$('#effect-source').value=name;renderEffects(name);showView('effects');});
  $$('[data-edit]').forEach(b=>b.onclick=()=>{const c=channels[+b.dataset.edit];openDialog('Edit channel',`<label for="channel-name">Channel name</label><input id="channel-name" required value="${escapeHTML(c.name)}" maxlength="30">`,'Save changes',()=>{c.name=$('#channel-name').value.trim()||c.name;renderChannels();});});
  $('#source-count').textContent=channels.length+' input channels';
}
function openDialog(title,html,action,callback){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;$('#dialog-submit').textContent=action;dialogCallback=callback;$('#dialog').showModal();}
$('#dialog-form').addEventListener('submit',event=>{if(event.submitter?.value==='cancel'){return;}if(!$('#dialog-form').checkValidity()){event.preventDefault();return;}dialogCallback?.();});
$('#monitor').onclick=()=>{monitoring=!monitoring;$('#monitor').textContent=monitoring?'◉ Monitoring on':'○ Monitoring off';toast(monitoring?'Monitor enabled in preview':'Monitor disabled in preview');};
$$('.output-range').forEach(input=>input.oninput=()=>{const card=input.closest('.output-card');$('.output-value',card).textContent=input.value+'%';$$('.horizontal-meter i',card).forEach((el,i)=>el.style.width=Math.max(0,+input.value-18-i*6)+'%');});
$$('.output-mute').forEach(b=>b.onclick=()=>{const pressed=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',pressed);b.textContent=pressed?'Unmute':'Mute';$$('.horizontal-meter i',b.closest('.output-card')).forEach(el=>el.style.opacity=pressed?'0':'1');});
const effectTemplates=[
  {name:'Noise gate',icon:'⌁',description:'Let your voice through. Leave the noise behind.',curve:'M0 100 L65 100 L110 30 L220 12',params:[['Threshold',-60,0,-42,'dB'],['Attack',0,100,10,'ms']]},
  {name:'Equalizer',icon:'≋',description:'A little warmth. A little presence. All you.',curve:'M0 72 C35 72 35 95 65 75 S100 63 125 69 S153 20 177 37 S200 55 220 49',params:[['Low cut',20,250,80,'Hz'],['Presence',-12,12,3,'dB']]},
  {name:'Compressor',icon:'⇥',description:'Keep things balanced, even in the big moments.',curve:'M0 108 L92 62 L220 27',params:[['Threshold',-60,0,-18,'dB'],['Ratio',1,12,4,':1']]}
];
const effectStates={};
function renderEffects(source='Microphone'){
  if(!effectStates[source]) effectStates[source]=effectTemplates.map((e,i)=>({...e,enabled:source==='Microphone'||(source==='Music'&&i===1),params:e.params.map(p=>[...p])}));
  const effects=effectStates[source];$('#effect-cards').innerHTML=effects.map((e,i)=>`<article class="effect-card ${e.enabled?'':'bypassed'}"><div class="effect-card-top"><span class="source-icon">${e.icon}</span><input class="switch" type="checkbox" aria-label="Enable ${e.name}" data-effect="${i}" ${e.enabled?'checked':''}></div><h3>${e.name}</h3><p>${e.description}</p><svg class="effect-graph" viewBox="0 0 220 120" preserveAspectRatio="none" role="img" aria-label="Illustrative ${e.name} response"><path class="grid" d="M0 30H220 M0 60H220 M0 90H220 M55 0V120 M110 0V120 M165 0V120"/><path class="curve" d="${e.curve}"/></svg>${e.params.map((p,j)=>`<div class="effect-param"><label for="param-${i}-${j}">${p[0]}<output id="value-${i}-${j}">${p[3]} ${p[4]}</output></label><input id="param-${i}-${j}" type="range" min="${p[1]}" max="${p[2]}" value="${p[3]}" data-effect-param="${i},${j}"></div>`).join('')}</article>`).join('');
  const updateChain=()=>{$('#chain-summary').textContent=[source,...effects.filter(e=>e.enabled).map(e=>e.name),'Output'].join(' → ');const channel=channels.find(c=>c.name===source);if(channel)channel.effects=effects.filter(e=>e.enabled).length;renderChannels();};
  $$('[data-effect]').forEach(input=>input.onchange=()=>{effects[+input.dataset.effect].enabled=input.checked;input.closest('.effect-card').classList.toggle('bypassed',!input.checked);updateChain();});
  $$('[data-effect-param]').forEach(input=>input.oninput=()=>{const [i,j]=input.dataset.effectParam.split(',').map(Number);effects[i].params[j][3]=+input.value;$(`#value-${i}-${j}`).textContent=input.value+' '+effects[i].params[j][4];});updateChain();
}
$('#effect-source').onchange=()=>renderEffects($('#effect-source').value);
const sounds=[{name:'Air horn',key:'F1',icon:'⚑',duration:'0:02',freq:220},{name:'Applause',key:'F2',icon:'✦',duration:'0:04',freq:640},{name:'Drum roll',key:'F3',icon:'◉',duration:'0:03',freq:110},{name:'Victory',key:'F4',icon:'♜',duration:'0:02',freq:523},{name:'Sad trombone',key:'F5',icon:'♫',duration:'0:03',freq:293},{name:'Mission complete',key:'F6',icon:'✓',duration:'0:02',freq:880}];
let audioContext;
function playSound(i){const sound=sounds[i];try{audioContext ||= new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const now=audioContext.currentTime;for(let n=0;n<3;n++){const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.type=i===0?'sawtooth':'sine';oscillator.frequency.value=sound.freq*(1+n*.25);gain.gain.setValueAtTime(0,now+n*.12);gain.gain.linearRampToValueAtTime(.045,now+n*.12+.02);gain.gain.exponentialRampToValueAtTime(.001,now+n*.12+.27);oscillator.connect(gain).connect(audioContext.destination);oscillator.start(now+n*.12);oscillator.stop(now+n*.12+.3);}}catch{toast('Audio preview is unavailable in this browser');return;}const card=$(`[data-sound-card="${i}"]`);card?.classList.add('playing');setTimeout(()=>card?.classList.remove('playing'),650);toast(sound.name+' · synthesized preview tone');}
function renderSounds(){$('#sound-grid').innerHTML=sounds.map((s,i)=>`<article class="sound-card" data-sound-card="${i}"><button class="sound-play" data-play="${i}" aria-label="Play ${escapeHTML(s.name)}">${s.icon}</button><h3>${escapeHTML(s.name)}</h3><p>Preview tone · ${s.duration}</p><div class="sound-card-bottom"><span>PRESS TO PLAY</span><button class="shortcut" data-shortcut="${i}" aria-label="Edit ${escapeHTML(s.name)} shortcut">${escapeHTML(s.key)}</button></div></article>`).join('');$$('[data-play]').forEach(b=>b.onclick=()=>playSound(+b.dataset.play));$$('[data-shortcut]').forEach(b=>b.onclick=()=>{const sound=sounds[+b.dataset.shortcut];openDialog('Set shortcut',`<p>Choose a key for ${escapeHTML(sound.name)}.</p><label for="shortcut-key">Shortcut</label><select id="shortcut-key">${Array.from({length:12},(_,i)=>`<option ${sound.key==='F'+(i+1)?'selected':''}>F${i+1}</option>`).join('')}</select><p class="hint">This prototype captures shortcuts while focused. System-wide registration belongs to the native audio application.</p>`,'Save shortcut',()=>{const key=$('#shortcut-key').value;const other=sounds.find(s=>s!==sound&&s.key===key);if(other)other.key=sound.key;sound.key=key;renderSounds();toast('Shortcut updated');});});}
$$('[data-sound]').forEach(b=>b.onclick=()=>playSound(sounds.findIndex(s=>s.name===b.dataset.sound)));
document.addEventListener('keydown',e=>{if($('#dialog').open||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;const i=sounds.findIndex(s=>s.key===e.key);if(i>=0){e.preventDefault();playSound(i);}if(!e.ctrlKey&&!e.altKey&&!e.metaKey&&['1','2','3','4'].includes(e.key))showView(['mixer','effects','soundboard','routing'][+e.key-1]);});
let nodes=[],connections=[],pendingPort=null;
function resetRouting(){const width=$('#routing-canvas').clientWidth||900;const nodeWidth=width<500?115:width<800?138:166;nodes=[{id:'mic',name:'Microphone',type:'INPUT',x:25,y:35},{id:'music',name:'Music',type:'INPUT',x:25,y:175},{id:'fx',name:'Voice processing',type:'EFFECTS',x:Math.max(30,(width-nodeWidth)/2),y:65},{id:'monitor',name:'Headphones',type:'OUTPUT',x:width-nodeWidth-25,y:35},{id:'stream',name:'Stream mix',type:'OUTPUT',x:width-nodeWidth-25,y:240}];connections=[['mic','fx'],['fx','monitor'],['fx','stream'],['music','stream']];renderNodes();}
function renderNodes(){const canvas=$('#routing-canvas');$$('.node',canvas).forEach(n=>n.remove());nodes.forEach(node=>{const el=document.createElement('div');el.className='node';el.dataset.node=node.id;el.tabIndex=0;el.setAttribute('role','group');el.setAttribute('aria-label',node.name+' node, arrow keys to move');el.style.left=node.x+'px';el.style.top=node.y+'px';el.innerHTML=`<div class="node-label">${node.type}</div><h3>${escapeHTML(node.name)}</h3><div class="node-bottom"><span>${node.type==='EFFECTS'?'3 effects':'Stereo'}</span><span>48 kHz</span></div>${node.type!=='INPUT'?'<button class="port in" aria-label="Connect to '+escapeHTML(node.name)+'"></button>':''}${node.type!=='OUTPUT'?'<button class="port out" aria-label="Connect from '+escapeHTML(node.name)+'"></button>':''}`;
  el.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;const sx=e.clientX,sy=e.clientY,ox=node.x,oy=node.y;el.setPointerCapture(e.pointerId);el.onpointermove=event=>{node.x=Math.max(7,Math.min(canvas.clientWidth-el.offsetWidth-7,ox+event.clientX-sx));node.y=Math.max(7,Math.min(canvas.clientHeight-el.offsetHeight-7,oy+event.clientY-sy));el.style.left=node.x+'px';el.style.top=node.y+'px';drawWires();};el.onpointerup=()=>el.onpointermove=null;});
  el.onkeydown=e=>{const moves={ArrowLeft:[-10,0],ArrowRight:[10,0],ArrowUp:[0,-10],ArrowDown:[0,10]};if(!moves[e.key]||e.target!==el)return;e.preventDefault();node.x=Math.max(7,Math.min(canvas.clientWidth-el.offsetWidth-7,node.x+moves[e.key][0]));node.y=Math.max(7,Math.min(canvas.clientHeight-el.offsetHeight-7,node.y+moves[e.key][1]));el.style.left=node.x+'px';el.style.top=node.y+'px';drawWires();};
  $('.out',el)?.addEventListener('click',e=>{pendingPort=node.id;$$('.port').forEach(p=>p.classList.remove('connecting'));e.target.classList.add('connecting');$('#routing-status').textContent='Connecting '+node.name+' — select a destination input port.';});
  $('.in',el)?.addEventListener('click',()=>{if(!pendingPort){toast('Choose an output port first');return;}const from=pendingPort;const reaches=(id,target,seen=new Set())=>{if(id===target)return true;if(seen.has(id))return false;seen.add(id);return connections.filter(c=>c[0]===id).some(c=>reaches(c[1],target,seen));};if(from===node.id||reaches(node.id,from)){toast('Feedback loops are not supported');return;}if(!connections.some(c=>c[0]===from&&c[1]===node.id))connections.push([from,node.id]);pendingPort=null;$$('.port').forEach(p=>p.classList.remove('connecting'));$('#routing-status').textContent='Connection added. Select a connection to remove it.';drawWires();});canvas.appendChild(el);});drawWires();}
function drawWires(){const canvas=$('#routing-canvas');if(!canvas.clientWidth)return;$('#wires').innerHTML=connections.map(([a,b],i)=>{const source=$(`[data-node="${a}"]`),target=$(`[data-node="${b}"]`);if(!source||!target)return '';const x1=parseFloat(source.style.left)+source.offsetWidth,y1=parseFloat(source.style.top)+42,x2=parseFloat(target.style.left),y2=parseFloat(target.style.top)+42,curve=Math.max(45,Math.abs(x2-x1)*.5);return `<path class="wire" d="M${x1},${y1} C${x1+curve},${y1} ${x2-curve},${y2} ${x2},${y2}" data-wire="${i}" tabindex="0" role="button" aria-label="Remove ${escapeHTML(nodes.find(n=>n.id===a).name)} to ${escapeHTML(nodes.find(n=>n.id===b).name)} connection"/>`;}).join('');$$('[data-wire]').forEach(w=>{const remove=()=>{connections.splice(+w.dataset.wire,1);drawWires();$('#routing-status').textContent='Connection removed.';};w.onclick=remove;w.onkeydown=e=>{if(['Enter',' ','Delete','Backspace'].includes(e.key)){e.preventDefault();remove();}};});}
$('#reset-routing').onclick=resetRouting;
new ResizeObserver(()=>{if(activeView!=='routing')return;const canvas=$('#routing-canvas');nodes.forEach(n=>{const el=$(`[data-node="${n.id}"]`);if(!el)return;n.x=Math.max(7,Math.min(canvas.clientWidth-el.offsetWidth-7,n.x));el.style.left=n.x+'px';});drawWires();}).observe($('#routing-canvas'));
$('#main-action').onclick=()=>{
  if(activeView==='mixer')openDialog('Add input channel','<label for="new-name">Channel name</label><input id="new-name" placeholder="e.g. Game audio" maxlength="30" required><label for="new-device">Input source</label><select id="new-device"><option>System default</option><option>Scarlett 2i2 · Input 1</option><option>Application audio</option><option>PirateWave Virtual Audio</option></select>','Add channel',()=>{channels.push({name:$('#new-name').value.trim()||'New input',device:$('#new-device').value,icon:'♩',color:'#b7a0f8',db:0,level:0,effects:0,pan:0,mute:false,solo:false});renderChannels();toast('Channel added');});
  if(activeView==='effects')openDialog('Add effect','<label for="new-effect">Effect</label><select id="new-effect"><option>Noise gate</option><option>Equalizer</option><option>Compressor</option></select><p class="hint">Enable an effect in the selected source’s processing chain.</p>','Enable effect',()=>{const source=$('#effect-source').value;const effect=effectStates[source].find(e=>e.name===$('#new-effect').value);effect.enabled=true;renderEffects(source);toast(effect.name+' enabled');});
  if(activeView==='soundboard')openDialog('Add sound','<label for="sound-name">Sound name</label><input id="sound-name" placeholder="e.g. Celebration" required maxlength="30"><p class="hint">New sounds use a synthesized preview tone. Audio file import will be provided by the native app.</p>','Add sound',()=>{const key=Array.from({length:12},(_,i)=>'F'+(i+1)).find(k=>!sounds.some(s=>s.key===k))||'Unassigned';sounds.push({name:$('#sound-name').value.trim()||'New sound',key,icon:'♫',duration:'0:01',freq:440});renderSounds();toast('Sound pad added');});
  if(activeView==='routing')openDialog('Add routing node','<label for="node-name">Node name</label><input id="node-name" required placeholder="e.g. Game audio" maxlength="30"><label for="node-type">Node type</label><select id="node-type"><option>INPUT</option><option>EFFECTS</option><option>OUTPUT</option></select>','Add node',()=>{nodes.push({id:'node-'+Date.now(),name:$('#node-name').value.trim()||'New node',type:$('#node-type').value,x:30,y:285});renderNodes();});
};
function bindScenes(){$$('.scene').forEach(b=>b.onclick=()=>{$$('.scene').forEach(s=>s.classList.remove('selected'));b.classList.add('selected');sceneName=b.textContent.replace('✓','').trim();$('.session-bar strong').textContent=sceneName;$('#scene-action span').textContent=sceneName;toast(sceneName+' selected · layout preview');});}bindScenes();
$('#scene-action').onclick=()=>openDialog('Choose a scene',`<label for="scene-choice">Scene</label><select id="scene-choice">${$$('.scene').map(s=>{const name=s.textContent.replace('✓','').trim();return `<option ${name===sceneName?'selected':''}>${escapeHTML(name)}</option>`;}).join('')}</select><p class="hint">Scene selection previews workspace organization.</p>`,'Select scene',()=>{const name=$('#scene-choice').value;$$('.scene').find(s=>s.textContent.replace('✓','').trim()===name)?.click();});
$('#new-scene').onclick=()=>openDialog('Save a scene','<label for="scene-name">Scene name</label><input id="scene-name" required placeholder="e.g. Podcast session" maxlength="30"><p class="hint">Scenes in this prototype are kept for the current session.</p>','Save scene',()=>{const button=document.createElement('button');button.className='scene';button.innerHTML='<span class="scene-dot"></span>'+escapeHTML($('#scene-name').value.trim()||'New scene');$('#scenes').appendChild(button);bindScenes();button.click();});
$('#settings').onclick=()=>openDialog('Audio settings','<label for="sample-rate">Sample rate</label><select id="sample-rate"><option>48,000 Hz</option><option>44,100 Hz</option><option>96,000 Hz</option></select><label for="buffer-size">Buffer size</label><select id="buffer-size"><option>256 samples</option><option>128 samples</option><option>512 samples</option></select><p class="hint">Settings preview only. No audio devices are accessed.</p>','Apply preview',()=>{const rate=$('#sample-rate').value,buffer=$('#buffer-size').value;$('.engine small').innerHTML=rate.replace(',000 Hz',' kHz').replace(',100 Hz','.1 kHz')+' <span>·</span> '+escapeHTML(buffer);toast('Audio settings preview updated');});
$('#help').onclick=()=>openDialog('Welcome to PirateWave','<p>Explore the mixer, adjust effect parameters, play sound preview tones, and connect draggable routing nodes.</p><p class="hint">Press 1–4 to change views. F1–F6 trigger sounds while the preview is focused. This design prototype does not mix real audio, discover devices, process effects, or register global shortcuts.</p>','Got it',()=>{});
renderChannels();renderEffects();renderSounds();resetRouting();
